observation.query:
SELECT DISTINCT ?graph ?subject ?predicate ?object
WHERE {
  VALUES ?graph {
    <urn:graphragprov:unit:u_1f8b303145f242b2>
    <urn:graphragprov:unit:u_27c0688f0cc0cdae>
    <urn:graphragprov:unit:u_8aaa8260007e2e9d>
    <urn:graphragprov:unit:u_d59d7261dbad2cb2>
  }
  GRAPH ?graph {
    ?subject ?predicate ?object .
    FILTER(isIRI(?subject))
  }
}
ORDER BY ?graph ?subject ?predicate ?object
